import { saveFictitiousReply } from '@/api/product';
export default {
  props: {
    visible: {
      type: Boolean,
      default: false,
    },
    goods: {
      type: Object,
      default() {
        return {};
      },
    },
    attr: {
      type: Object,
      default() {
        return {};
      },
    },
    avatar: {
      type: Object,
      default() {
        return {};
      },
    },
    picture: {
      type: Array,
      default() {
        return [];
      },
    },
  },
  data() {
    return {
      formData: {
        avatar: '',
        nickname: '',
        comment: '',
      },
      product_score: 0,
      service_score: 0,
      delivery_score: 0,
      reply_score: '3',
      pics: [],
      add_time: '',
    };
  },
  watch: {
    picture(value) {
      this.pics = value.map((item) => {
        return item.att_dir;
      });
    },
    visible(value) {
      if (!value) {
        this.formData.nickname = '';
        this.formData.comment = '';
        this.product_score = 0;
        this.service_score = 0;
        this.add_time = '';
      }
    },
  },
  methods: {
    removeUser(){
      this.avatar.att_dir = '';
    },
    removePicture(att_id) {
      this.$emit('removePicture', att_id);
    },
    onChange(date) {
      this.add_time = date;
    },
    callGoods() {
      this.$emit('callGoods');
    },
    callAttr() {
      this.$emit('callAttr');
    },
    callPicture(type) {
      this.$emit('callPicture', type);
    },
    onOk() {
      if (!this.goods.id) {
        return this.$Message.error('请选择商品');
      }
      if (!this.attr.unique) {
        return this.$Message.error('请选择商品规格');
      }
      if (!this.avatar.att_dir) {
        return this.$Message.error('请选择用户头像');
      }
      if (!this.formData.nickname) {
        return this.$Message.error('请填写用户昵称');
      }
      if (!this.formData.comment) {
        return this.$Message.error('请填写评论内容');
      }
      if (!this.product_score) {
        return this.$Message.error('商品分数必须是1-5之间的整数');
      }
      if (!this.service_score) {
        return this.$Message.error('服务分数必须是1-5之间的整数');
      }
      let data = {
        image: {
          image: this.goods.image,
          product_id: this.goods.id,
        },
        unique: this.attr.unique,
        avatar: this.avatar.att_dir,
        nickname: this.formData.nickname,
        comment: this.formData.comment,
        product_score: this.product_score,
        service_score: this.service_score,
        delivery_score: this.delivery_score,
        reply_score: this.reply_score,
        pics: this.pics,
        add_time: this.add_time,
      };
      saveFictitiousReply(data)
        .then((res) => {
          this.$Message.success(res.msg);
          this.$emit('update:visible', false);
        })
        .catch((res) => {
          this.$Message.error(res.msg);
        });
    },
    onCancel() {
      this.$emit('update:visible', false);
    },
  },
};
